def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            version_part, build = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release (everything after '-')
        if '-' in version_part:
            base_part, prerelease = version_part.split('-', 1)
            prerelease_ids = prerelease.split('.')
        else:
            base_part = version_part
            prerelease_ids = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1, [])

        # Pre-release sorts before release
        key_parts = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers compare numerically and sort before non-digit
                key_parts.append((0, int(identifier)))
            else:
                # Non-digit identifiers compare by ASCII
                key_parts.append((1, identifier))

        return (0, key_parts)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_ids = parse_version(version)
        pre_key = prerelease_key(prerelease_ids)
        # Return tuple for sorting: (major, minor, patch, prerelease_key, original_index)
        # The original_index ensures stable sort for equal precedence
        return (major, minor, patch, pre_key, index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

